    {
      "card": "Business Silver Rewards Card",
      "documented_return": "Normally 1.0% cash back on other purchases; a listed limited-time promotion doubles eligible rewards for six months",
      "estimated_reward_on_100000": {
        "at_normal_1_percent_rate": "$1,000",
        "at_2_percent_promotional_rate": "$2,000"
