      "apr": "18.99% on carried balances",
      "credit_limit": "$17,500 to $112,500, subject to approval",
      "eligibility": "Minimum personal FICO score of 700; established businesses may qualify with PAYDEX of at least 47",
      "important_note": "The listed double-cash-back promotion ends November 14, 2025, so its availability must be confirmed before relying on it. The card may also be approved for only slightly more than the planned $100,000 charge."
    },
    {
      "card": "Green Rewards Card",
      "documented_return": "3.0% at qualifying sustainable or eco-friendly merchants; 1.0% otherwise",
      "estimated_reward_on_100000": {
        "if_Apple_Music_qualifies_as_sustainable": "$3,000",
